// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // ensure target is not the zero address to avoid non-reverting call
        vm.assume(target != address(0));
        // bound value to 1 ether to keep balance manageable
        value = bound(value, 0, 1 ether);

        // first deposit via fallback
        (bool ok1,) = address(c).call{value: 1 wei}("");
        assertTrue(ok1);

        // attempt sendMoney
        (bool ok2, bytes memory data) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // Rule: the contract balance must equal depositsCount (each deposit adds exactly 1 wei)
        // The reference version always succeeds regardless of sendMoney outcome, so depositsCount remains unchanged.
        // The mutated version reverts if the call fails, but the balance is unchanged and depositsCount is unchanged.
        // However, to distinguish: the reference never reverts (so ok2 is always true), the mutant reverts on failure (ok2 false).
        // But externally we just compare balance: reference C always has balance == depositsCount (depositsCount incremented once).
        // For the reference: true. For mutant: if sendMoney reverts, the 1 wei is still there, so balance == depositsCount -> true.
        // Wait: need a rule that the reference satisfies and mutant breaks. The reference never reverts (ok2 always true), mutant may revert. So rule: sendMoney always succeeds.
        assertTrue(ok2);
    }
}

